# perbaikan salah ketik yang disengaja diperiksa: hapus kata aneh pada satu kalimat
baris = [(k, j, r, c.replace("memeriksa semangat kebersamaan", "menunjukkan semangat kebersamaan")) for k, j, r, c in baris]

asli = pd.read_csv("dataset_asli.csv")
tambah = pd.DataFrame(baris, columns=["kategori", "judul", "ringkasan", "konten"])[["judul", "ringkasan", "konten", "kategori"]]
gabung = pd.concat([asli, tambah], ignore_index=True)
gabung["sumber"] = ["asli"] * len(asli) + ["tambahan"] * len(tambah)
assert not gabung.judul.duplicated().any()
gabung.to_csv("dataset_desa_tempel.csv", index=False, quoting=csv.QUOTE_NONNUMERIC, encoding="utf-8")
print(gabung.groupby(["kategori", "sumber"]).size().unstack())
print("total:", len(gabung))
